            background: transparent;
            padding: 8px 16px;
            border-radius: 8px;
            font-family: inherit;
            font-size: 1rem;
            color: var(--text-muted);
            cursor: pointer;
            transition: all 0.3s ease;
            position: relative;
        }
        .tab-button::after {
            content: '';
            position: absolute;
            bottom: -2px;
            left: 50%;
            transform: translateX(-50%);
            width: 0;
            height: 2px;
            background: var(--primary-glow);
            transition: width 0.3s ease;
        }
        .tab-button.active {
            color: var(--text-gold);
            text-shadow: 0 0 5px var(--shadow-color);
        }
        .tab-button.active::after {
            width: 80%;
        }
        .tab-panel {
            display: none;
            flex-direction: column;
            gap: 16px;
        }
        .tab-panel.active {
            display: flex;
        }
        .panel-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 16px;
        }
        .panel-block {
            background: rgba(0, 0, 0, 0.2);
            border-radius: 12px;
            padding: 16px;
            display: flex;
            flex-direction: column;
            gap: 14px;
        }
        .panel-title {
            font-size: 1.2rem;
            color: var(--primary-glow);
            border-bottom: 1px solid var(--border-color);
            padding-bottom: 8px;
            margin-bottom: 4px;
        }
        .attribute-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 12px;
        }
        .info-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 0.95rem;
        }
        .info-label {
            color: var(--text-muted);
        }
        .info-value {
            font-weight: bold;
            color: var(--text-main);
        }
        .progress-bar-container {
            width: 100%;
            height: 10px;
            background: rgba(0, 0, 0, 0.4);
            border-radius: 5px;
            overflow: hidden;
            margin-top: 5px;
        }
        .progress-bar-value {
            height: 100%;
            transition: width 0.5s cubic-bezier(0.25, 1, 0.5, 1);
            border-radius: 5px;
        }
        .metric-card {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }
        .metric-header {
            display: flex;
            justify-content: space-between;
            align-items: baseline;
        }
        .item-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 8px;
        }
        .item-list li {
            background: rgba(0,0,0,0.2);
            padding: 8px 12px;
            border-radius: 6px;
            font-size: 0.9rem;
            display: flex;
            justify-content: space-between;
        }
        .item-name {
            color: var(--text-main);
        }
        .item-count {
            color: var(--text-muted);
        }
        .thoughts-text {
            font-style: italic;
            color: var(--text-muted);
            line-height: 1.6;
            padding: 10px;
            background: rgba(0,0,0,0.15);
            border-radius: 8px;
            border-left: 3px solid var(--accent-jade);
        }
        .empty-tip {
            color: var(--text-muted);
            text-align: center;
            padding: 20px;
        }
        .error-tip {
            color: #ff8a80;
            background: rgba(229, 57, 53, 0.2);
            border: 1px solid var(--accent-fire);
            border-radius: 12px;
            padding: 16px;
            text-align: center;
        }
    </style>
</head>
<body>
<div class="status-card" id="status-card">
