    <nav class="tab-strip" role="tablist">
        <button type="button" class="tab-button active" data-tab="player" onclick="switchTab('player', this)">侠者档案</button>
        <button type="button" class="tab-button" data-tab="companion" id="companion-tab" onclick="switchTab('companion', this)" style="display:none;">红颜知己</button>
        <button type="button" class="tab-button" data-tab="achievements" onclick="switchTab('achievements', this)">成就</button>
        <button type="button" class="tab-button" data-tab="world" onclick="switchTab('world', this)">天下大势</button>
    </nav>

    <div id="tab-content-player" class="tab-panel active">
        <div class="panel-grid">
            <div class="panel-block">
                <h2 class="panel-title">基础属性</h2>
                <div class="metric-card">
                    <div class="metric-header"><span class="info-label">等级</span><span class="info-value" id="player-level"></span></div>
                </div>
                <div class="metric-card">
                    <div class="metric-header"><span class="info-label">经验</span><span class="info-value"><span id="player-exp"></span> / <span id="player-exp-cap"></span></span></div>
                    <div class="progress-bar-container"><div id="player-exp-bar" class="progress-bar-value" style="background: var(--primary-glow);"></div></div>
