                <div class="metric-card">
                    <div class="metric-header"><span class="info-label">内力</span><span class="info-value"><span id="player-mp"></span> / <span id="player-mp-cap"></span></span></div>
                    <div class="progress-bar-container"><div id="player-mp-bar" class="progress-bar-value" style="background: var(--accent-jade);"></div></div>
