                <div class="attribute-grid">
                    <div class="info-item"><span class="info-label">攻击力</span><span class="info-value" id="player-atk"></span></div>
                    <div class="info-item"><span class="info-label">防御力</span><span class="info-value" id="player-def"></span></div>
                    <div class="info-item"><span class="info-label">声望</span><span class="info-value" id="player-rep"></span></div>
                    <div class="info-item"><span class="info-label">正邪</span><span class="info-value" id="player-align"></span></div>
                    <div class="info-item"><span class="info-label">称号</span><span class="info-value" id="player-title"></span></div>
                </div>
            </div>
            <div class="panel-block">
                <h2 class="panel-title">行囊 & 装备</h2>
