                <div class="info-item"><span class="info-label">武器</span><span class="info-value" id="player-weapon"></span></div>
                <div class="info-item"><span class="info-label">防具</span><span class="info-value" id="player-armor"></span></div>
                <h3 class="panel-title" style="margin-top: 10px; font-size: 1.1rem;">物品</h3>
