</div>

<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        return current === undefined || current === null ? defaultValue : current;
    }

    function updateProgressBar(barId, valueMainId, valueCapId, rawValue, rawCapValue, color) {
        const bar = document.getElementById(barId);
        const main = document.getElementById(valueMainId);
        const cap = document.getElementById(valueCapId);
        if (!bar || !main || !cap) return;

        const numValue = parseFloat(rawValue);
        const numCap = parseFloat(rawCapValue);

        main.innerText = !isNaN(numValue) ? numValue : rawValue;
        cap.innerText = !isNaN(numCap) ? numCap : rawCapValue;

        if (!isNaN(numValue) && !isNaN(numCap) && numCap > 0) {
            const percentage = (numValue / numCap) * 100;
            bar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            if (color) bar.style.background = color;
        } else {
            bar.style.width = '0%';
        }
    }

    function switchTab(tabName, tabElement) {
        document.querySelectorAll('.tab-button').forEach(tab => tab.classList.remove('active'));
        document.querySelectorAll('.tab-panel').forEach(content => content.classList.remove('active'));
        if (tabElement) {
            tabElement.classList.add('active');
            document.getElementById('tab-content-' + tabName).classList.add('active');
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            const gameData = messages?.[0]?.data;
            const characterData = gameData?.stat_data;

            if (!characterData) {
                document.getElementById('status-card').innerHTML = "<div class='error-tip'>未能加载角色数据。</div>";
                return;
            }

            document.getElementById('current-time').innerText = SafeGetValue(characterData, '世界.当前时间');
            document.getElementById('current-location').innerText = SafeGetValue(characterData, '世界.当前地点');

            const player = SafeGetValue(characterData, '玩家', {});
            const playerAttr = SafeGetValue(player, '属性', {});
            const playerDeriv = SafeGetValue(player, '衍生属性', {});
            const playerBag = SafeGetValue(player, '背包', {});
            const playerAchiev = SafeGetValue(player, '成就', {});

            document.getElementById('player-level').innerText = SafeGetValue(playerAttr, '等级');
            updateProgressBar('player-exp-bar', 'player-exp', 'player-exp-cap', SafeGetValue(playerAttr, '经验值'), SafeGetValue(playerAttr, '升级所需经验'));
            updateProgressBar('player-hp-bar', 'player-hp', 'player-hp-cap', SafeGetValue(playerAttr, '气血'), SafeGetValue(playerAttr, '气血上限'));
            updateProgressBar('player-mp-bar', 'player-mp', 'player-mp-cap', SafeGetValue(playerAttr, '内力'), SafeGetValue(playerAttr, '内力上限'));

            document.getElementById('player-atk').innerText = SafeGetValue(playerAttr, '攻击力');
            document.getElementById('player-def').innerText = SafeGetValue(playerAttr, '防御力');
            document.getElementById('player-rep').innerText = SafeGetValue(playerDeriv, '声望');
            document.getElementById('player-align').innerText = SafeGetValue(playerDeriv, '正邪值');
            document.getElementById('player-title').innerText = SafeGetValue(playerAchiev, '当前称号', '无');

            document.getElementById('player-money').innerText = `${SafeGetValue(playerBag, '金钱')} 文`;
            const weapon = SafeGetValue(player, '装备.武器', {名称: '无'});
            document.getElementById('player-weapon').innerText = weapon.名称 || '无';
            const armor = SafeGetValue(player, '装备.防具.身体', {名称: '无'});
            document.getElementById('player-armor').innerText = armor.名称 || '无';

            const inventoryElem = document.getElementById('player-inventory');
            const inventory = SafeGetValue(playerBag, '物品', []);
            inventoryElem.innerHTML = inventory.length > 0 ? inventory.map(item => `<li><span class="item-name">${item.名称}</span><span class="item-count">×${item.数量}</span></li>`).join('') : '<li class="empty-tip">空空如也</li>';

            const skills = SafeGetValue(player, '武学.内功', []).concat(SafeGetValue(player, '武学.招式', []));
            const skillsElem = document.getElementById('player-skills');
            skillsElem.innerHTML = skills.length > 0 ? skills.map(s => `<li><span class="item-name">${s.名称}</span><span class="item-count">Lv.${s.等级}</span></li>`).join('') : '<li class="empty-tip">尚未习武</li>';

            const mainQuests = SafeGetValue(player, '任务.主线任务', []);
            const sideQuests = SafeGetValue(player, '任务.支线任务', []);
            const dailyQuests = SafeGetValue(player, '任务.日常任务', []);
            const allQuests = mainQuests.concat(sideQuests, dailyQuests);
            const questsElem = document.getElementById('player-quests');
            questsElem.innerHTML = allQuests.length > 0 ? allQuests.map(q => `<li><span class="item-name">[${q.任务类型 || '任务'}] ${q.任务名}</span></li>`).join('') : '<li class="empty-tip">暂无任务</li>';

            const achievements = SafeGetValue(playerAchiev, '已获得成就', []);
            const achievementsElem = document.getElementById('player-achievements');
            achievementsElem.innerHTML = achievements.length > 0 ? achievements.map(ach => `<li><span class="item-name">${ach}</span></li>`).join('') : '<li class="empty-tip">尚未获得任何成就</li>';

            const meijing = SafeGetValue(characterData, 'NPC关系.梅静', null);
            const companionTab = document.getElementById('companion-tab');
            if (meijing && meijing.是否同行) {
                companionTab.style.display = 'block';
                document.getElementById('companion-name').innerText = '梅静';
                const favor = SafeGetValue(meijing, '好感度', 0);
                document.getElementById('companion-favor').innerText = favor;
                document.getElementById('companion-favor-bar').style.width = `${favor}%`;
                document.getElementById('companion-relation').innerText = SafeGetValue(meijing, '关系状态');
                document.getElementById('companion-inteam').innerText = '同行中';
                const meijingState = SafeGetValue(meijing, '当前状态', {});
                document.getElementById('companion-mood').innerText = SafeGetValue(meijingState, '情绪');
                document.getElementById('companion-outfit').innerText = SafeGetValue(meijingState, '当前着装');
                document.getElementById('companion-pose').innerText = SafeGetValue(meijingState, '当前姿势');
                document.getElementById('companion-thoughts').innerText = SafeGetValue(meijingState, '当前想法');
            } else {
                companionTab.style.display = 'none';
            }

            const world = SafeGetValue(characterData, '世界', {});
            document.getElementById('world-weather').innerText = SafeGetValue(world, '当前天气');
            document.getElementById('world-season').innerText = SafeGetValue(world, '当前季节');
            document.getElementById('world-news').innerText = `江湖动态：${SafeGetValue(world, '江湖动态')}`;

            const factions = SafeGetValue(characterData, '势力关系', {});
            const factionsElem = document.getElementById('faction-relations');
            let factionHtml = '';
            for (const key in factions) {
                if (Object.prototype.hasOwnProperty.call(factions, key)) {
                    factionHtml += `<li><span class="item-name">${key}</span><span class="item-count">${factions[key].关系状态} (${factions[key].关系值})</span></li>`;
                }
            }
            factionsElem.innerHTML = factionHtml || '<li class="empty-tip">无</li>';

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<div class='error-tip'>状态栏加载时发生错误: ${error.message}</div>`;
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>
