        <div class="start-button-container">
            <button class="start-btn" onclick="startGame()">开始江湖路</button>
        </div>
    </div>


    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const music = document.getElementById('bg-music');
            if (music) {
                music.volume = 0.3;
            }
        });

        function switchMainTab(tabId, element) {
            document.querySelectorAll('.tab-panel').forEach(panel => panel.classList.remove('active'));
            document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
            document.getElementById(tabId).classList.add('active');
            element.classList.add('active');
        }

        function switchLeaderboardTab(tabId, element) {
            document.querySelectorAll('.leaderboard-panel').forEach(panel => panel.classList.remove('active'));
            document.querySelectorAll('.leaderboard-tab-btn').forEach(btn => btn.classList.remove('active'));
            document.getElementById(tabId).classList.add('active');
            element.classList.add('active');
        }

        let swordHeartInterval;
        let swordHeartScore;
        let swordHeartTimer;

        function startSwordHeartTest() {
            const testArea = document.getElementById('sword-heart-test-area');
            const target = document.getElementById('sword-heart-target');
            const resultDisplay = document.getElementById('sword-heart-result');
            const startButton = event.target;

            testArea.style.display = 'block';
            startButton.style.display = 'none';
            resultDisplay.textContent = '准备...';
            swordHeartScore = 0;

            let timeLeft = 15;

            target.onclick = () => {
                swordHeartScore++;
                resultDisplay.textContent = `得分: ${swordHeartScore} | 剩余时间: ${timeLeft}s`;
                moveTarget();
            };

            const moveTarget = () => {
                const areaRect = testArea.getBoundingClientRect();
                const targetRect = target.getBoundingClientRect();
                const x = Math.random() * (areaRect.width - targetRect.width);
                const y = Math.random() * (areaRect.height - targetRect.height);
                target.style.left = `${x}px`;
                target.style.top = `${y}px`;
            };

            moveTarget();

            clearInterval(swordHeartInterval);
            clearTimeout(swordHeartTimer);

            swordHeartInterval = setInterval(() => {
                timeLeft--;
                resultDisplay.textContent = `得分: ${swordHeartScore} | 剩余时间: ${timeLeft}s`;
                if(timeLeft <= 0) {
                    clearInterval(swordHeartInterval);
                    testArea.style.display = 'none';
                    startButton.style.display = 'inline-block';
                    let finalComment = "剑心不稳，仍需磨砺。";
                    if(swordHeartScore >= 15) finalComment = "剑心通明，天赋异禀！";
                    else if(swordHeartScore >= 10) finalComment = "剑心沉稳，未来可期。";
                    resultDisplay.textContent = `试炼结束！得分: ${swordHeartScore}。评价: ${finalComment}`;
                }
            }, 1000);
        }

        function playReactionGame(playerMove) {
            const moves = ['灵蛇出洞', '力劈华山', '随风摆柳'];
            const computerMove = moves[Math.floor(Math.random() * moves.length)];
            const resultDisplay = document.getElementById('move-result');

            let resultText = `你出招: ${playerMove}，对手出招: ${computerMove}。`;

            if (playerMove === computerMove) {
                resultText += "平分秋色！";
            } else if (
                (playerMove === '灵蛇出洞' && computerMove === '随风摆柳') ||
                (playerMove === '力劈华山' && computerMove === '灵蛇出洞') ||
                (playerMove === '随风摆柳' && computerMove === '力劈华山')
            ) {
                resultText += "你技高一筹！";
            } else {
                resultText += "对手棋高一着。";
            }
            resultDisplay.textContent = resultText;

            triggerSlash(`/echo ${resultText}`);
        }

        function startGame() {
            if (typeof triggerSlash === 'function') {
                triggerSlash('/send 开始江湖路 | /trigger');
            }
        }
    </script>
</body>
</html>
